import { company } from '../data/company';

/**
 * The official Tyllage logo (public/logo/2.png) — a symbol without a
 * wordmark, so the brand name is set beside it. Small derivatives generated by
 * scripts/generate-brand-assets.mjs keep the header light; the original
 * file is the fallback.
 */
export function Logo({ tone = 'dark', showWordmark = true }: { tone?: 'dark' | 'light'; showWordmark?: boolean }) {
  return (
    <span className={`logo logo--${tone}`}>
      <span className="logo__mark">
        <img
          src={company.logo}
          srcSet="/logo/tyllage-logo-96.webp 96w, /logo/tyllage-logo-144.webp 144w"
          sizes="48px"
          width={48}
          height={48}
          alt={showWordmark ? '' : company.brandName}
          decoding="async"
        />
      </span>
      {showWordmark && <span className="logo__word">{company.brandName}</span>}
    </span>
  );
}
